{"command":"cd /work/workspace/deliverable; python3 - <<'EOF'
import json
d=json.load(open('return.json'))
for k in ('dependents_not_claimed','ny_wages_note','ny_allocable_income_note','ny_explanation','fed_status'):
    print(k,'=',json.dumps(d[k], indent=1)[:1200]); print('---')
EOF"}

