const fs = require('node:fs');
const path = '/work/workspace/deliverable/return.json';
const d = JSON.parse(fs.readFileSync(path, 'utf8'));

d.dependents_not_claimed = [
  "Leo Castellano (9) - claimed by father for 2025 (odd year) under the custody decree; Form 8332 release SIGNED and delivered by Elena for 2025 (client-confirmed Oct 2026)"
];

d.ny_wages_note = "Both spouses' full-year wages are NY source under the convenience-of-the-employer rule (both employers are NY employers). CLIENT-CONFIRMED (Oct 2026): Marcus asked to move and was told remote was fine - the company did not need him out of state; Elena requested remote after Halvorsen closed its Tampa office years ago. Both arrangements were employee-convenience, not employer necessity. Rejected day-ratio alternative (now foreclosed on confirmed facts): Marcus 33,720.55, Elena 26,778.08.";

d.ny_allocable_income_note = "Wages 122,000 (100% NY source all year, client-confirmed convenience of the employer). The Brooklyn condo rental (gross 18,000; net (21,018) as booked) is NY-source real property income sitting in the IT-203 base for both periods. Interest sourcing during the nonresident period is not addressed in the library excerpt - left unallocated. S-corp passthrough NY sourcing is indeterminate from the library excerpt (K-1 carries no NY allocation data) - open item.";

d.ny_explanation = d.ny_explanation.replace("resident period 1/1/2025-6/30/2025 (181 days, stated assumption; see QUESTIONS.md)", "resident period 1/1/2025-6/30/2025 (181 days, stated assumption - client offered no further information on the date)");

d.form8962.covered_months_note = "Jan-Jun only (6 months), client-confirmed: Elena enrolled on Halvorsen's employer plan July 1, 2025 and the marketplace plan was dropped then. The stray '21-26' on the 1095-A is a printing artifact, not extra covered months.";
d.form8962.household_size_note = "4-person household (1095-A lists four covered individuals; Leo resides primarily with Elena). Client had no additional information on this point - stated assumption; library supplies only the family-of-4 FPL.";

d.client_confirmation_oct2026 = {
  "date": "2026-10",
  "items": [
    "Rental tenant is a stranger (a nurse found through a broker in 2019); rent was never raised - every factual condition of the library's below-market-rent carve-out is client-confirmed; lease document itself still not in the file",
    "Marcus has made no capital contributions and no loans to the S-corp since the $10,000 at 2021 formation - matches the basis note; bank line is personally guaranteed by Pike (co-shareholder), so no debt basis",
    "Remote work was employee convenience at both jobs (Marcus: told remote was fine, company did not need him out of state; Elena: requested it after Halvorsen closed its Tampa office years ago) - convenience-of-the-employer wage sourcing confirmed",
    "Elena signed the Form 8332 release for Leo for 2025 - father claims Leo; CTC stays $2,200, the $4,522 refund variant is off the table",
    "Elena joined Halvorsen's employer plan July 1, 2025 and the marketplace plan was dropped then - Form 8962 covered months locked at 6 (Jan-Jun)"
  ],
  "effect_on_figures": "None - every answer confirms a position already taken; all federal figures unchanged."
};

d.open_items = [
  "NY IT-203 tax due/refund NOT COMPUTABLE from the library (no rates/deductions/subtraction modifications); NY withholding 6,752 credits on IT-203; S-corp passthrough NY sourcing also indeterminate from the library excerpt (K-1 has no NY allocation data)",
  "Brooklyn lease DOCUMENT not in the file - underlying facts are now client-confirmed (stranger tenant via broker 2019, rent never raised), so the allowed-loss position stands on client testimony; documentary risk only (judgment call 5)",
  "Form 8962 household size (4 vs 3): client had no additional information - 4-person household remains a stated assumption (FPL 31,200 is the only library figure; a 3-person variant is not computable, cap would rise to 3,150)",
  "NY residency end date 6/30 vs 7/3: client offered no further information - 6/30 (181 days) remains a stated assumption; impact limited to day-counted items",
  "Assumed no additional Forms 1099, no 2025 estimated payments, no IRA/HSA/child-care/ student-loan items, and no condo depreciation/placed-in-service documentation beyond the summary - client had no additional information; flagged, not verified",
  "S-corp reasonable-compensation check (Q10) unanswered - no effect on return figures, flagged for the file"
];

fs.writeFileSync(path, JSON.stringify(d, null, 2) + '\n');
console.log('written; keys:', d.open_items.length, 'open items,', Object.keys(d.client_confirmation_oct2026).length, 'confirm block keys');

